"""Load configuration from files and strings."""

import os

from miniconf.errors import ConfigError
from miniconf.parser import parse_lines

INCLUDE_DIRECTIVE = "@include"


def _read_lines(path):
    with open(path, "r", encoding="utf-8") as fh:
        return fh.read().splitlines()


def _expand(path, lines, stack):
    """Return ``lines`` (from ``path``) with ``@include`` directives expanded.

    ``stack`` holds the real paths of the files currently being expanded and
    is used to detect include cycles.
    """
    base = os.path.dirname(path)
    expanded = []
    for lineno, raw in enumerate(lines, start=1):
        parts = raw.strip().split(None, 1)
        if not parts or parts[0] != INCLUDE_DIRECTIVE:
            expanded.append(raw)
            continue
        if len(parts) < 2:
            raise ConfigError(
                "{} line {}: @include requires a path".format(path, lineno)
            )
        target = os.path.join(base, parts[1].strip())
        real = os.path.realpath(target)
        if real in stack:
            raise ConfigError(
                "include cycle detected: {}".format(" -> ".join(stack + [real]))
            )
        try:
            child_lines = _read_lines(target)
        except OSError as exc:
            raise ConfigError(
                "{} line {}: cannot include {!r}: {}".format(
                    path, lineno, parts[1].strip(), exc.strerror or exc
                )
            ) from exc
        expanded.extend(_expand(target, child_lines, stack + [real]))
    return expanded


def load(path):
    """Read and parse the configuration file at ``path``.

    ``@include <path>`` lines are replaced in place by the full contents of the
    referenced file (resolved relative to the including file's directory),
    recursively. Missing include targets and include cycles raise
    :class:`~miniconf.errors.ConfigError`.
    """
    lines = _read_lines(path)
    return parse_lines(_expand(path, lines, [os.path.realpath(path)]))


def loads(text):
    """Parse configuration from a string."""
    return parse_lines(text.splitlines())
